/// <summary>
/// AVA/WEN/20250109    AVA_012791_CredManBlockExclusionRules
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(CredManTable, CredManReleasePostingDialog), FormControlEventType::DialogClosed)]
public static void CredManReleasePostingDialog_OnDialogClosed(FormControl sender, FormControlEventArgs e)
{
    SalesTable  salesTable;
    CredManTable credManTable;

    if (Box::yesNo("@NDX:NXACredExcludeSO", DialogButton::Yes) == DialogButton::Yes)
    {
        ttsbegin;
        credManTable = sender.formRun().dataSource(formDataSourceStr(CredManTable,CredManTable)).cursor();
        salesTable = salesTable::find(credManTable.SalesId, true);
        salesTable.CredManExcludeSalesOrder = NoYes::Yes;
        salesTable.update();
        ttscommit;

    }
}
